// Menu links entered in the admin (or generated by its "add from sources"
// picker) use legacy / generic paths such as /category/<slug>, /brand/<slug>,
// /about-us or /track-order. The storefront has no pages at those paths, so
// they are translated here to the real routes.

/** Special value for a menu item: expands to the live category tree (Shop by Category). */
export const CATEGORIES_TOKEN = '@categories';

const FIXED = {
  '/products': '/shop',
  '/shop': '/shop',
  '/home': '/home',
  '/about': '/about',
  '/contact-us': '/contact',
  '/terms': '/terms-conditions',
  '/terms-and-conditions': '/terms-conditions',
  '/privacy': '/privacy-policy',
  '/returns': '/return-policy',
  '/craft-of-india': '/crafts-of-india',
  '/track-order': '/orders',
  '/orders/tracking': '/orders',
  '/order-tracking': '/orders',
  '/track': '/orders',
  '/my-account': '/profile',
  '/account': '/profile',
  '/journal': '/blog',
  '/blogs': '/blog',
  '/vendors': '/vendor/register',
  '/become-a-vendor': '/vendor/register',
};

const titleFromSlug = (slug) =>
  decodeURIComponent(slug)
    .split('-')
    .filter(Boolean)
    .join(' ');

/** True for links that leave the site (rendered as a normal anchor). */
export const isExternalUrl = (url) => /^(https?:)?\/\//i.test(url || '') || /^(mailto|tel):/i.test(url || '');

/**
 * Turn a menu URL into a working storefront path.
 * @param {string} url
 * @param {Array<{name:string, slug:string}>} categories live category tree
 */
export const resolveMenuUrl = (url, categories = []) => {
  const raw = String(url || '').trim();
  if (!raw) return '/home';
  if (isExternalUrl(raw)) return raw;
  const path = raw.startsWith('/') ? raw : `/${raw}`;
  const [pathname, query = ''] = path.split('?');
  const clean = pathname.replace(/\/+$/, '') || '/';

  if (FIXED[clean]) {
    // keep the search/category part of /shop?... and /products?...
    if (FIXED[clean] === '/shop' && query && /(^|&)(category|search)=/.test(query)) return `/shop?${query}`;
    return FIXED[clean];
  }

  const cat = clean.match(/^\/(?:category|product-category|product-categories|categories)\/(.+)$/);
  if (cat) {
    const slug = cat[1].split('/').pop();
    const found = categories.find((c) => c.slug === slug) || categories.find((c) => c.name.toLowerCase() === titleFromSlug(slug).toLowerCase());
    return found ? `/shop?category=${encodeURIComponent(found.name)}` : '/shop';
  }

  const brand = clean.match(/^\/brands?\/(.+)$/);
  if (brand) return `/shop?brand=${encodeURIComponent(brand[1].toLowerCase())}`;

  if (/^\/blog\/category\//.test(clean)) return '/blog';

  return path;
};
